# while needs its own guard against an endless loop
attempts <- 0
while (attempts < 3) {
  attempts <- attempts + 1
}
attempts # 3

# next skips one iteration, break leaves the loop
for (n in 1:10) {
  if (n %% 2 == 0) next
  if (n > 7) break
  cat(n, " ")
}
# 1 3 5 7

# Defaults make the common call short
compound <- function(principal, rate, years = 1, times = 12) {
  principal * (1 + rate / times) ^ (times * years)
}

compound(1000, 0.12)             # 1126.825
compound(1000, 0.12, years = 5)  # 1816.697

# return() exits early with an explicit value
safe_div <- function(a, b) {
  if (b == 0) {
    return(NA_real_)
  }
  a / b
}
safe_div(10, 0) # NA
